INSERT INTO cv_records (id, message_id, sender_email, sender_name, subject, received_date, candidate_name, candidate_email, candidate_phone, candidate_city, category, seniority, experience_years, key_skills, summary, portfolio_links, file_name, file_path, preview_token, status, reported, created_at, pros, cons, cover_letter) VALUES (1, '<CAHKpj7QOcHWCSj5gfDAFT34VXu8744p6MzLGTGgZN6O5HKpwsw@mail.gmail.com>_20261024_153728_e59158_Hilal_Korkmaz_CV', 'hiilallkorkmaz@gmail.com', 'Hilal Korkmaz', 'Social First Copywriter İş Başvurusu Hk.', 'Fri, 23 Oct 2026 21:12:03 +0300', 'Hilal Korkmaz', 'hiilallkorkmaz@gmail.com', '+90 554 130 6751', 'İstanbul', 'Social Media & Copywriting', 'Senior', '6 Yıl', 'Copywriting, Sosyal Medya Stratejisi, SEO, Meta Business Suite, Adobe Premiere, İçerik Planlama', 'Aday, sosyal medya yönetimi ve metin yazarlığı alanında operasyonel süreçlere hakim bir profil çiziyor. Ancak, sık iş değiştirmesi ve portfolyo sunmaması, ajansımızın uzun vadeli beklentileri ve yaratıcı kalite standartlarımız açısından mülakat aşamasında detaylı sorgulanmalıdır.', '', 'Hilal Korkmaz CV.pdf', 'E:\cv-system\storage\cvs\20261024_153728_e59158_Hilal_Korkmaz_CV.pdf', '5ae5ff5e359d4f73919e56fd9fce62a3', 'processed', 1, '2026-10-24 12:37:33', ' • Farklı sektörlerden gelen marka deneyimi ile geniş bir içerik üretim yelpazesine sahip olması
 • SEO ve sosyal medya metin yazarlığı konusunda pratik tecrübesi
 • Video düzenleme araçlarına (Premiere, CapCut) hakimiyet', ' • Kısa süreli iş değişiklikleri (ortalama 1 yıl veya altı) istikrar konusunda soru işareti yaratıyor
 • CV''de belirtilen ''Senior'' unvanı ile 6 yıllık toplam deneyim süresi, ajans standartlarımıza göre kıdem beklentisi açısından tekrar değerlendirilmelidir
 • Portfolyo linki paylaşılmamış; yaratıcı çıktıların kalitesini doğrulamak için ek çalışma gerektiriyor', 'Merhaba,

6 senedir aktif olarak metin yazarlığı ve sosyal medya uzmanlığı yapıyorum.
İş yaptığım süre boyunca ekibim ve yöneticilerim arasında köprü görevi
görerek işlerin eksiksiz ilerlemesini sağladım. Kriz yönetimi yapabilen,
sorunlara değil çözümlere odaklanan, 2 sene boyunca Yazarlık Okulu''na
gitmenin verdiği bilgi birikimi yazdığı her kompozisyonda kullanabilen
biriyim. Çalıştığım tüm pozisyonlarda ekibimle uyum içerisinde çalışmış,
işleri takip etmiş ve zamanlamaya çok dikkat etmişimdir. Çalıştığım tüm
markalarla iletişimimi oldukça kuvvetli, nazik ve çözüm odaklı sürdürdüm.

İş Bankası Kültür Yayınları, Rossmann Türkiye gibi büyük markalarla çalışma
tecrübem bulunmaktadır.

Bu pozisyon ile ilgili yetenek ve becerilerimi size aktarmaktan büyük bir
keyif duyarım.

Teşekkür ederim,
Hilal Korkmaz');
INSERT INTO cv_records (id, message_id, sender_email, sender_name, subject, received_date, candidate_name, candidate_email, candidate_phone, candidate_city, category, seniority, experience_years, key_skills, summary, portfolio_links, file_name, file_path, preview_token, status, reported, created_at, pros, cons, cover_letter) VALUES (10, '<CAETAHwjmR--FgRqYhBPsFf_m0q8J4sv+dUZzZrOp87mSY4Sk6w@mail.gmail.com>_20261024_153925_e0c1ee_OZAN_OĞURLU_CV.pdf', 'ozanogurluu@gmail.com', 'Ozan Oğurlu', 'Social First Copywriter Başvurusu- Ozan Oğurlu', 'Fri, 23 Oct 2026 23:37:45 +0300', 'Ozan Oğurlu', 'ozanogurluu@gmail.com', '0536 613 54 62', 'İstanbul', 'Creative Copywriting', 'Junior', '1 Yıl', 'Metin Yazarlığı, İçerik Üretimi, 360° Kampanya Kurgusu, Dijital İletişim, Photoshop, Illustrator', 'Aday, staj süreçlerinde çeşitli markalarla çalışma fırsatı bulmuş ve temel reklamcılık disiplinlerine aşinadır. Ancak, pozisyonun kapsamına dair sergilediği direnç ve beklentisi, ajansın mevcut ihtiyaçları ve hiyerarşik yapısı ile uyum konusunda soru işareti yaratmaktadır.', 'https://www.behance.net/ozanogurlu', 'OZAN OĞURLU_CV.pdf.pdf', 'E:\cv-system\storage\cvs\20261024_153925_e0c1ee_OZAN_OĞURLU_CV.pdf.pdf', 'dc92258d956b49ca9204c0110707ee41', 'processed', 1, '2026-10-24 12:39:30', ' • Farklı ölçeklerdeki markalarla staj süreçlerinde çalışarak ajans iş akışına dair temel deneyim kazanmış olması.
 • Üniversite döneminde katıldığı yarışmalarda kampanya kurgulama ve uygulama konusunda somut başarılar elde etmesi.', ' • İlan edilen ''Social First'' pozisyonuna karşı ön yargılı bir tutum sergileyerek kendi rol tanımını dayatmaya çalışması.
 • Staj geçmişinin kısa süreli ve parçalı olması, derinlemesine bir uzmanlık alanının henüz oluşmadığını gösteriyor.', 'Merhaba,

Ben Ozan Oğurlu. Beykent Üniversitesi Reklamcılık Bölümü mezunuyum. Daha
önce hem content writerlık hem de copywriterlık staj deneyimlerim
bulunuyor. Sizlerin yaptığı işleri beğeniyor ve takip ediyorum. Sizlerle
çalışmak isterim.

Copywriterlık pozisyonunun sadece social olması biraz tedirgin etse de
sizlerle tanışmak ve konuşmak isterim. Social yerine Jr. Copywriter olarak
başlamak ve tabii ki social kısmında da bulunmak isterim. Umarım tanışma ve
konuşma fırsatımız olur.

Şimdiden vaktinizi ayırdığınız için teşekkür ederim. İyi çalışmalar
diliyorum.

CV’mi ekte bulabilirsiniz. Portfolyomu ise CV’mde bulunan Behance
profilimden inceleyebilirsiniz.

Saygılarımla,');
INSERT INTO cv_records (id, message_id, sender_email, sender_name, subject, received_date, candidate_name, candidate_email, candidate_phone, candidate_city, category, seniority, experience_years, key_skills, summary, portfolio_links, file_name, file_path, preview_token, status, reported, created_at, pros, cons, cover_letter) VALUES (11, '<CA+e-b8rWzCb_kxOt9FOFedNCgKczUOkUWH1whX7yP5bVra5RcQ@mail.gmail.com>_20261024_153930_61783d_Semih_Sengul_CV_TR', 'ssemihsengul@gmail.com', 'Semih Şengül', 'İş Başvurusu Hk.', 'Sat, 24 Oct 2026 00:40:01 +0300', 'Semih Şengül', 'ssemihsengul@gmail.com', '+90 539 269 20 89', 'Antalya', 'Sosyal Medya ve Dijital İletişim', 'Senior', '8 Yıl', 'Sosyal Medya Stratejisi, Topluluk Yönetimi, Performans Analizi, Sosyal Dinleme, Meta/YouTube/LinkedIn Reklam Yönetimi, Kriz Yönetimi', 'Semih, sosyal medya yönetimi ve veri analitiği konusunda oldukça deneyimli bir aday. Teknik araçlara hakimiyeti ve kampanya yönetimi başarısı dikkat çekici olsa da, İngilizce seviyesinin düşüklüğü ve lokasyon kısıtı, ajansın operasyonel ihtiyaçları açısından değerlendirilmesi gereken risk faktörleridir.', 'https://linkedin.com/in/semihsengul', 'Semih_Sengul_CV_TR.pdf', 'E:\cv-system\storage\cvs\20261024_153930_61783d_Semih_Sengul_CV_TR.pdf', 'b6a73562060b47fcadab2473ace674b9', 'processed', 1, '2026-10-24 12:39:33', ' • Farklı sektörlerde geniş marka portföyü deneyimi
 • Veri odaklı raporlama ve sosyal dinleme araçlarına hakimiyet
 • Organik büyüme ve kampanya yönetimi konusunda somut başarı örnekleri', ' • Antalya''da ikamet etmesi ve uzaktan çalışma tercihi, ajansın operasyonel dinamikleri için bir kısıt oluşturabilir
 • İngilizce seviyesinin A2 olması, global projelerde iletişim bariyeri yaratabilir
 • Kariyer geçmişinde kısa süreli (3-4 aylık) çalışma dönemleri mevcut', 'Merhaba,

Sosyal medya yönetimi, topluluk yönetimi, içerik stratejisi, performans
analizi ve raporlama alanlarında 8 yıllık deneyime sahip bir sosyal medya
yöneticisiyim. Sağlık, ilaç, teknoloji, finans, havacılık ve FMCG
sektörlerinde global ve yerel markalarla çalıştım.

Çalıştığım ajanstan ay sonu itibarıyla ayrılıyorum, kasım ayından itibaren
yeni bir pozisyona başlayabilirim. Antalya’da yaşıyorum. Uzaktan
çalışabilirim, hibrit modelde belirli dönemlerde İstanbul’da bulunabilirim.

Sosyal medya, pazarlama, strateji ve dijital alanlardaki pozisyonlarda
değerlendirilmek üzere özgeçmişimi ekte paylaşıyorum. Uygun görürseniz kısa
bir görüşme yapabiliriz.

Teşekkürler,
Semih Şengül');
INSERT INTO cv_records (id, message_id, sender_email, sender_name, subject, received_date, candidate_name, candidate_email, candidate_phone, candidate_city, category, seniority, experience_years, key_skills, summary, portfolio_links, file_name, file_path, preview_token, status, reported, created_at, pros, cons, cover_letter) VALUES (12, '<CAD1=Pf1-DFmOOLmy4fqk00A-__wd2srtnt3_jTpOyEVq2DneRA@mail.gmail.com>_20261024_153933_7cebe2_F_Buse_Mazi_Cv', 'buse.fatmamazi@gmail.com', 'Buse Mazı', 'Başvuru: Jr. Strategist - Buse Mazı', 'Sat, 24 Oct 2026 09:53:49 +0300', 'Fatma Buse Mazı', 'buse.fatmamazi@gmail.com', '0539 788 24 13', 'İstanbul', 'Strateji ve İletişim', 'Junior', '1 Yıl', 'Marka İletişimi, Influencer Marketing, Medya Raporlama, İçerik Planlama, Adobe Illustrator & Photoshop', 'Aday, çeşitli staj deneyimleriyle ajans işleyişine dair temel bir fikir edinmiş olsa da, stratejist rolünün gerektirdiği analitik derinlik ve yaratıcı kampanya kurgulama konusunda henüz kanıtlanmış bir yetkinliğe sahip değildir. Nabulu bünyesinde değerlendirilmesi için, stratejik düşünme becerisini somutlaştıracak bir portfolyo veya vaka analizi sunması şarttır.', 'https://www.linkedin.com/in/buse-mazi', 'F_Buse_Mazi_Cv.PDF', 'E:\cv-system\storage\cvs\20261024_153933_7cebe2_F_Buse_Mazi_Cv.PDF', 'f478387c90274647a6f744f7482a34bf', 'processed', 1, '2026-10-24 12:39:37', ' • Farklı kurumlarda tamamlanmış çoklu staj deneyimi ile operasyonel süreçlere aşinalık.
 • Influencer araştırması, medya takibi ve raporlama gibi temel ajans iş akışlarında pratik bilgi sahibi olması.
 • Akademik ve gönüllü projelerle desteklenmiş aktif bir özgeçmiş.', ' • Strateji rolü için gerekli olan derinlemesine veri analizi ve kampanya kurgulama konusunda somut bir portfolyo veya vaka çalışması sunulmamış.
 • İş tecrübesi tamamen staj odaklı olduğu için, profesyonel bir ajans ortamında inisiyatif alma ve kriz yönetimi konularında yetkinliği belirsiz.
 • Teknik beceriler (Adobe, SPSS) temel seviyede kalıyor, strateji üretimi için gerekli olan ileri düzey araç hakimiyeti eksik.', 'Merhaba Nabulu Ekibi,

​LinkedIn üzerindeki Jr. Strategist ilanınızı görerek özgeçmişimi sizinle
paylaşmak istedim.

​İstanbul Aydın Üniversitesi Halkla İlişkiler ve Tanıtım 2025 Lisans
mezunuyum. Stajlarımı sırasıyla Can Medya Grubu (Ciner Yayın Holding),
Brandworks İletişim Danışmanlığı ve I STALK IN Dijital Reklam Ajansı’nda
tamamladım. Bu süreçte marka iletişimi ve marka yönetimi süreçlerinde yer
aldım.

​Marka stratejisi ve yaratıcı kampanya süreçlerinde ekibinize katkı
sağlamayı çok isterim. Güncel özgeçmişim ektedir.
​İnceleme şansınız olursa çok sevinirim.

​İyi çalışmalar dilerim.

​Saygılarımla,

Fatma Buse Mazı
0539 788 24 13
buse.fatmamazi@gmail.com');
INSERT INTO cv_records (id, message_id, sender_email, sender_name, subject, received_date, candidate_name, candidate_email, candidate_phone, candidate_city, category, seniority, experience_years, key_skills, summary, portfolio_links, file_name, file_path, preview_token, status, reported, created_at, pros, cons, cover_letter) VALUES (13, '<FE7CD6C4-D28D-48D2-8B10-14F051BB4BDC@gmail.com>_20261024_153937_01ab40_Burcu_Gizem_Özkök_CV', 'burcugizem.ozkok@gmail.com', 'Burcu Gizem Özkök', 'Yazar', 'Sat, 24 Oct 2026 11:00:00 +0300', 'Burcu Gizem Özkök', 'burcugizem.ozkok@gmail.com', '0554 396 12 22', 'Belirtilmemiş', 'Creative Copywriting', 'Lead / Direktör', '13 Yıl', 'Creative Direction, Copywriting, Kampanya Kurgusu, Marka İletişimi, Kristal Elma Ödüllü Kreatif Süreçler', 'Aday, sektörde uzun yıllara dayanan bir tecrübeye ve güçlü bir kampanya geçmişine sahiptir. Ancak, sık iş değiştirme eğilimi ve sadece uzaktan çalışma konusundaki ısrarlı tutumu, ajansın operasyonel dinamikleri ve ekip içi entegrasyonu açısından değerlendirilmelidir.', 'https://www.linkedin.com/in/burcu-gizem-ozkok-500b4138/', 'Burcu Gizem Özkök CV.pdf', 'E:\cv-system\storage\cvs\20261024_153937_01ab40_Burcu_Gizem_Özkök_CV.pdf', 'a6cf5a653daa41fdb85961c06b8ac95a', 'processed', 1, '2026-10-24 12:39:41', ' • 16 yıllık geniş kapsamlı reklam yazarlığı ve ekip yönetimi tecrübesi.
 • FMCG, finans ve teknoloji gibi farklı sektörlerdeki marka deneyimi ve ödüllü iş çıktıları.', ' • Kariyer geçmişinde sık iş değişikliği gözlemlenmektedir.
 • Tam zamanlı ofis içi çalışma düzenine uyum sağlayıp sağlamayacağı belirsizdir; sadece uzaktan çalışma modeline odaklı bir beklentisi bulunmaktadır.', 'Selamlar, yazar arayışınız üzerine yazıyorum. 
16 yıl deneyimliyim, headlik tecrübem de var. 
Uzaktan çalışıyorum. Full remote''a açıksanız tanışalım.');
INSERT INTO cv_records (id, message_id, sender_email, sender_name, subject, received_date, candidate_name, candidate_email, candidate_phone, candidate_city, category, seniority, experience_years, key_skills, summary, portfolio_links, file_name, file_path, preview_token, status, reported, created_at, pros, cons, cover_letter) VALUES (14, '<CAPeC1VfrnerbcVfSJbi_WPE-p7iFqa_QXySi8YmP2d2BzCnrDg@mail.gmail.com>_20261024_153942_0fd567_Selen_Tatar_Creative_Strategist_Resume_(1)', 'st.selentatar@gmail.com', 'selen tatar', 'Copywriter / Content Writer Başvuru', 'Sat, 24 Oct 2026 11:20:42 +0300', 'Selen Tatar', 'st.selentatar@gmail.com', '0531 368 67 19', 'İstanbul', 'Creative Copywriter & Strategist', 'Mid-Level', '2.5 Yıl', 'Creative Copywriting, Strategic Planning, Social Psychology, Content Strategy, Public Speaking, Research', 'Selen Tatar, psikoloji temelli stratejik bakış açısı ve ajans deneyimiyle orta seviye bir pozisyon için potansiyel barındırıyor. Ancak, sık iş değiştirme eğilimi ve portfolyosundaki işlerin derinliği konusunda temkinli olunmalı; teknik yetkinliği ve ajans kültürümüze adaptasyonu mülakat aşamasında netleştirilmelidir.', 'https://www.behance.net/selentatar1', 'Selen Tatar Creative Strategist Resume (1).pdf', 'E:\cv-system\storage\cvs\20261024_153942_0fd567_Selen_Tatar_Creative_Strategist_Resume_(1).pdf', 'da5cef87dc7a402d8ecfae03099b1a6d', 'processed', 1, '2026-10-24 12:39:48', ' • Psikoloji disiplininden gelen akademik altyapısını stratejik planlama ve tüketici içgörüsü süreçlerine entegre edebiliyor.
 • Farklı ajans yapılarında çeşitli sektörlerden markalarla çalışma deneyimine sahip.
 • Yaratıcı yazarlığın yanı sıra ekip yönetimi ve iş takibi konusunda sorumluluk üstlenmiş.', ' • Yaklaşık 2.5 yıllık süreçte üç farklı kurumda çalışmış olması, istikrar konusunda soru işareti yaratıyor.
 • Portfolyosundaki işlerin bir kısmı kampanya bazlı olmaktan ziyade genel içerik üretimi odaklı görünüyor; büyük ölçekli kampanya kurgulama yetkinliği derinlemesine incelenmeli.
 • Akademik geçmişi güçlü olsa da, reklamcılık teknikleri ve yaratıcı çıktıların Nabulu''nun yüksek tempo ve özgünlük standartlarını karşılayıp karşılamayacağı mülakatta test edilmeli.', 'Merhabalar,

Ben Selen. LinkedIn''deki ilanınıza istinaden size ulaşıyorum.

Çankaya Üniversitesi Psikoloji mezunuyum. Sosyal psikolojiye olan ilgimi
yaratıcılıkla birleştirmek istediğim için reklamcılığa yöneldim; Jellybon
ve Senfonico gibi ajanslarda metin yazarlığı yaptım.

Şu an Askıda Ne Var’da üniversite öğrencileri için sosyal fayda projeleri
üretiyor ve markalara gençlik iletişim stratejileri hazırlıyorum. Yaklaşık
bir yıldır yaratıcı ekibin ve iş takibinin sorumluluğunu da üstleniyorum.

İş dışında sinema, tiyatro ve heykel gibi farklı disiplinlerle ilgileniyor,
dergilerde yazılar yazıyorum. Meraklı ve sürekli üreten yapımın
yaratıcılığımı her zaman beslediğine inanıyorum.

Kariyerime yeni beceriler kazanabileceğim ve yaratıcılığıma daha fazla alan
açabileceğim markalarla devam etmek istiyorum.

Kişisel bilgilerime ekteki CV''mden, ajans deneyimlerime ise portfolyomdan
ulaşabilirsiniz:
Ajans İşlerim <https://www.behance.net/selentatar1>

Bakış açım ve üslubum konusunda fikir verebileceğini düşündüğüm için heykel
portfolyomu ve yayımlanan son yazımı iletiyorum.

Heykel Portfolyo
<https://drive.google.com/drive/u/0/folders/1KJInal5FVPnyl1DSFNJJ3flvrSvzLkmo>
Yayımlanan Son Yazım <https://terrabayt.com/author/selen/>

Sizinle tanışmayı ve ekibinizin bir parçası olmayı çok isterim.

Geri dönüşünüzü bekliyorum.

Sevgiler,

Selen TATAR.');
INSERT INTO cv_records (id, message_id, sender_email, sender_name, subject, received_date, candidate_name, candidate_email, candidate_phone, candidate_city, category, seniority, experience_years, key_skills, summary, portfolio_links, file_name, file_path, preview_token, status, reported, created_at, pros, cons, cover_letter) VALUES (15, '<CAPLgqyAQ0cziYpLnxgrOT-uiBSgh4sgeRvYdcwtNuXDT+CjtDA@mail.gmail.com>_20261024_153948_983b1c_Melisa_Selin_Fırat', 'm.selinfirat@gmail.com', 'Selin Fırat', 'İş Başvurusu Hakkında', 'Sat, 24 Oct 2026 11:27:47 +0300', 'Melisa Selin Fırat', 'm.selinfirat@gmail.com', '0539 888 8724', 'İstanbul', 'Strateji ve Operasyon', 'Junior', '1 Yıl', 'SAP, Canva, Microsoft Office, Pazarlama İletişimi, Operasyonel Finans, Müşteri İlişkileri', 'Aday, finansal operasyonlar ve veri analizi konusunda teknik bir altyapıya sahip olsa da reklamcılık disiplini için henüz yolun başındadır. Strateji veya operasyonel destek rollerinde değerlendirilebilir ancak yaratıcı süreçlerdeki yetkinliği belirsizdir; bu nedenle ajansın operasyonel ihtiyaçları doğrultusunda bir görüşme yapılabilir.', '', 'Melisa Selin Fırat.pdf', 'E:\cv-system\storage\cvs\20261024_153948_983b1c_Melisa_Selin_Fırat.pdf', '1f1543ccb2e14787908300aee30ac346', 'processed', 1, '2026-10-24 12:39:56', ' • E-ticaret operasyonları ve finansal süreçlerde somut deneyim sahibi olması
 • Reklam ve marka stratejisi süreçlerine dair temel staj tecrübesi bulunması
 • Analitik düşünme ve veri odaklı raporlama yetkinliği', ' • Kariyer odağının finans/operasyon ile reklamcılık arasında netleşmemiş olması
 • Yaratıcı bir pozisyon için gerekli olan portfolyo veya somut kampanya çıktısı sunmaması
 • Ajans dinamiklerine uyum sağlayıp sağlayamayacağı konusunda henüz yeterli profesyonel kanıtın bulunmaması', 'Merhabalar,

Linkedin üzerinden paylaştığınız iş ilanınız üzerine tarafınıza
ulaşmaktayım. Güncel olarak Bilgi Üniversitesi Pazarlama İletişimi yüksek
lisans programında okuyorum. İş ilanınızla ilgileniyorum. CV’m ekte
iletilmiştir. Geri dönüşlerinizi beklemekteyim.

İyi çalışmalar dilerim.');
